'use strict';
const byId = id => document.getElementById(id);
const initialDraft = 'Keep the same note when the space changes.';
const chapters = [
 {short:'Available space',title:'Adapt to the available space',description:'A screen-sized frame can outlive the display it was measured on. Size content from the current view and let a navigation container adapt its panes.',task:'Choose Fragile implementation and drag the width below 520 demo units. Then switch to Adaptive implementation at that same width.',takeaway:'Use current view geometry and adaptive containers. The 520-unit pane budget here is a teaching choice, not an iPhone Duo breakpoint or size-class rule.',code:'NavigationSplitView {\n    NoteList()\n} detail: {\n    NoteDetail()\n}\n\n// For a custom UIKit layout:\nlet available = view.bounds.inset(\n    by: view.safeAreaInsets\n)\n// Re-read when the view size changes.',file:'AvailableSpace.swift',note:'NavigationSplitView: iOS 16+ · Never infer an actual size class from this demo’s slider.',source:'https://developer.apple.com/documentation/swiftui/navigationsplitview'},
 {short:'Reserved regions',title:'Keep controls clear of the fold',description:'Safe-area insets describe edges. They do not describe the center fold. Custom controls need to consider division and camera occlusion regions too.',task:'Select Book with Fragile implementation to see Compose overlap the fold. Turn on the inner camera, then switch to Adaptive implementation.',takeaway:'Query division and occlusion regions in the coordinate space you lay out. Prefer system containers; move custom controls only as much as needed.',code:'// iOS 27.1+, inside a GeometryReader\nlet folds = geometry.reservedRegions(\n    kind: .division\n)\nlet cameras = geometry.reservedRegions(\n    kind: .occlusion\n)\n\n// Their frames are in this view’s coordinates.\n// Keep custom text and tap targets clear.\n// Re-query when relevant geometry changes.',file:'ReservedRegions.swift',note:'Fold changes may occur without a resize. Verify that your layout updates correctly; no universal reserved-region change callback is promised here.',source:'https://developer.apple.com/documentation/swiftui/reservedregion'},
 {short:'System controls',title:'Let the system place your controls',description:'System containers choose placement. Inner landscape uses side controls; inner portrait and this tabletop example use horizontal controls. A homemade bottom bar stays where you put it.',task:'With Adaptive implementation selected, switch between Book and Tabletop. Compare the system control placement, then inspect the Swift tab.',takeaway:'Declare destinations and labeled actions in system containers. Read toolbarVerticalEdge for custom UI that needs the actual bar placement; don’t derive it from a hinge angle.',code:'NavigationStack {\n    NotesView()\n        .toolbar {\n            Button("Compose",\n                   systemImage: "square.and.pencil",\n                   action: compose)\n        }\n}\n\n// iOS 27.1+, for custom content:\n@Environment(\\.toolbarVerticalEdge)\nprivate var toolbarEdge',file:'ContainerOwnedBars.swift',note:'toolbarVerticalEdge is an optional HorizontalEdge. A nil value means the toolbar is not on a vertical edge. This is a pattern, not a full View declaration.',source:'https://developer.apple.com/documentation/swiftui/environmentvalues/toolbarverticaledge'},
 {short:'State continuity',title:'Preserve the task across displays',description:'Opening or closing a full-screen app resizes its scene. It is not a reason to throw away selection or editing state. Try changing the note itself, then changing the space.',task:'Choose Adaptive implementation, edit the note, and switch displays. Your exact draft should remain. Fragile implementation deliberately resets its separate demo draft on a display change.',takeaway:'Keep selection and drafts in a stable model owned above the changing layout. Real scene disconnection and restoration are separate concerns from a full-screen fold transition.',code:'@Observable\nfinal class EditorModel {\n    var draft = ""\n    var selectedNoteID: UUID?\n}\n\nstruct EditorRoot: View {\n    @State private var model = EditorModel()\n\n    var body: some View {\n        AdaptiveEditor(model: model)\n    }\n}\n// Keep this owner stable across layout changes.',file:'EditorState.swift',note:'Observation: iOS 17+ · Import SwiftUI, Observation, and Foundation in your app. AdaptiveEditor is your view. This is one scene’s in-memory state, not disk persistence.',source:'https://developer.apple.com/forums/thread/847644'},
 {short:'Put it together',title:'Combine geometry, regions, and state',description:'Now combine a constrained app window, an active camera, and an existing draft. Use the controls to investigate, then choose an implementation below the lab.',task:'Inspect the narrow Split View scenario. Read the Signals or Swift panel, then answer the scenario below.',takeaway:'Available geometry, reserved regions, system containers, and stable state work together. A clean browser demo is not proof that an iOS app is ready—build it and test the real transitions.',code:'// A review sequence, not a pose switch:\n// 1. Read the current view’s available bounds.\n// 2. Let system containers place bars and panes.\n// 3. Query .division / .occlusion for custom UI.\n// 4. Keep the current model and selection.\n// 5. Test resize, fold, camera, and multitasking.\n\n// Never use an arbitrary hinge-angle threshold\n// as a replacement for layout information.',file:'ReviewChecklist.swift',note:'Full display and system side-bar behavior require building with the iOS 27.1 SDK or later. Use availability guards when supporting older iOS versions.',source:'https://developer.apple.com/iphone-duo/prepare/'}
];
const surfaces={outer:{label:'Outer display',width:360,bars:'Side · camera edge'},open:{label:'Inner · open',width:760,bars:'Side'},book:{label:'Inner · book',width:760,bars:'Side'},tabletop:{label:'Inner · tabletop',width:650,bars:'Horizontal'},split:{label:'Split View · right app',width:420,bars:'Side · right outer edge'}};
const state={chapter:0,surface:'open',width:760,camera:false,regions:true,mode:'adaptive',draft:initialDraft,fragileDraft:initialDraft,note:'Learning to adapt',fragileNote:'Learning to adapt',complete:new Set(),flags:{},trace:[],seq:0};
let toastTimer;
function log(message){state.trace.unshift({n:++state.seq,message});state.trace=state.trace.slice(0,12);renderTrace();}
function renderTrace(){byId('event-trace').replaceChildren(...state.trace.map(event=>{const li=document.createElement('li');const small=document.createElement('small');small.textContent=`ACTION ${String(event.n).padStart(2,'0')}`;li.append(small,document.createTextNode(event.message));return li;}));}
function toast(message){byId('lab-toast').textContent=message;byId('lab-toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>byId('lab-toast').classList.remove('visible'),2800);}
function isFold(){return state.surface==='book'||state.surface==='tabletop';}
function draftValue(){return state.mode==='adaptive'?state.draft:state.fragileDraft;}
function noteValue(){return state.mode==='adaptive'?state.note:state.fragileNote;}
function updateProgress(){
 const completed=state.complete.has(state.chapter);
 byId('course-progress').value=state.complete.size;
 byId('journey-progress').textContent=`${state.complete.size} of 5 experiments completed`;
 byId('chapter-status').textContent=completed?'✓ Completed. Continue when you’re ready.':'Use the preview controls to try it.';
 byId('chapter-status').className=completed?'done':'';
 for(const button of document.querySelectorAll('#chapter-nav button')){const i=Number(button.dataset.chapter);button.setAttribute('aria-current',i===state.chapter?'step':'false');button.dataset.complete=String(state.complete.has(i));button.querySelector('span').textContent=state.complete.has(i)?'✓':String(i+1).padStart(2,'0');}
 byId('completion').hidden=state.complete.size!==5;
}
function checkCompletion(){
 const f=state.flags;
 if(state.chapter===0){if(state.width<520){if(state.mode==='fragile')f.narrowFragile=true;else if(f.narrowFragile)state.complete.add(0);}}
 if(state.chapter===1){if(state.surface==='book'&&state.mode==='fragile')f.foldFragile=true;if(state.camera)f.cameraTried=true;if(f.foldFragile&&f.cameraTried&&state.mode==='adaptive'&&state.surface==='book')state.complete.add(1);}
 if(state.chapter===2&&state.mode==='adaptive'){if(state.surface==='book')f.barBook=true;if(state.surface==='tabletop')f.barTable=true;if(f.barBook&&f.barTable&&f.barCode)state.complete.add(2);}
 updateProgress();
}
function setTab(key,focus=false){for(const b of document.querySelectorAll('[data-tab]')){const active=b.dataset.tab===key;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;byId(`${b.dataset.tab}-panel`).hidden=!active;if(active&&focus)b.focus();}if(key==='swift'&&state.chapter===2){state.flags.barCode=true;checkCompletion();}}
function setChapter(index){state.chapter=Math.max(0,Math.min(4,index));const c=chapters[state.chapter];byId('chapter-number').textContent=`EXPERIMENT ${String(state.chapter+1).padStart(2,'0')} / 05`;byId('chapter-title').textContent=c.title;byId('chapter-description').textContent=c.description;byId('chapter-task').textContent=c.task;byId('takeaway-text').textContent=c.takeaway;byId('swift-code').textContent=c.code;byId('snippet-title').textContent=c.file;byId('snippet-note').textContent=c.note;byId('snippet-source').href=c.source;byId('previous-chapter').disabled=state.chapter===0;byId('next-chapter').textContent=state.chapter===4?'Back to first experiment ↺':'Next experiment →';byId('challenge').hidden=state.chapter!==4;
 if(state.chapter===4){state.surface='split';state.width=420;state.camera=true;state.mode='adaptive';log('Combined scenario loaded: narrow app, active inner camera, existing model retained.');}
 setTab('signals');render();checkCompletion();
 if(window.matchMedia('(max-width:760px)').matches){const selected=document.querySelector(`#chapter-nav [data-chapter="${state.chapter}"]`);selected.scrollIntoView({block:'nearest',inline:'nearest'});}
}
function render(){
 const s=surfaces[state.surface],compact=state.width<520,fold=isFold(),adaptive=state.mode==='adaptive',camera=state.surface==='outer'||state.camera;
 const device=byId('demo-device');Object.assign(device.dataset,{surface:state.surface,mode:state.mode,compact:String(compact),camera:String(state.camera&&state.surface!=='outer'),regions:String(state.regions)});device.style.width=`${72+(state.width-320)/580*28}%`;
 byId('surface-label').textContent=s.label;byId('app-width').value=String(state.width);byId('width-value').textContent=`${state.width} demo units`;byId('camera-active').disabled=state.surface==='outer';byId('camera-active').checked=state.camera;byId('show-regions').checked=state.regions;
 byId('note-title').textContent=noteValue();if(byId('draft').value!==draftValue())byId('draft').value=draftValue();
 for(const button of document.querySelectorAll('[data-surface]')){if(button.tagName==='BUTTON')button.setAttribute('aria-pressed',String(button.dataset.surface===state.surface));}
 for(const button of document.querySelectorAll('[data-note]'))button.setAttribute('aria-pressed',String(button.dataset.note===noteValue()));
 byId('fragile-mode').setAttribute('aria-pressed',String(!adaptive));byId('adaptive-mode').setAttribute('aria-pressed',String(adaptive));
 const issue=!adaptive;byId('demo-feedback').dataset.problem=String(issue);
 byId('demo-feedback').textContent=adaptive?(fold?'The custom action stays in a usable region. System containers handle the navigation layout.':compact?'One detail pane fits the available budget. Selection and draft remain in the model.':'The list and detail share the available space. Keep the same task when it shrinks.'):(fold?'Compose overlaps the division region. A centered custom control can look visible but be hard to use.':compact?'A fixed 620-unit layout is clipped by the smaller app window. The selected note can fall out of view.':'The fixed layout looks plausible here. Shrink the width or select Book to expose its assumptions.');
 byId('implementation-note').textContent=adaptive?'Adaptive: current view budget, system bar placement, region-aware custom action, stable editing model.':'Fragile: fixed content width, homemade bottom bar, centered custom action, draft reset on display changes. Intentionally broken for comparison.';
 const signals=[['view width',`${state.width} demo units`],['pane budget',compact?'One pane (< 520 in this model)':'Two panes (≥ 520 in this model)'],['system bars',s.bars],['active regions',`${fold?'.division':''}${fold&&camera?' + ':''}${camera?'.occlusion':''}${!fold&&!camera?'None in this scenario':''}`],['full-screen scene',state.surface==='split'?'Multitasking: observe actual scene state':'Same scene · active'],['selection',noteValue()],['draft owner',adaptive?'Stable model':'Recreated layout state']];
 byId('signal-list').replaceChildren(...signals.map(([label,value])=>{const div=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;div.append(dt,dd);return div;}));
 let title,body;
 if(!adaptive){title='The code still assumes the old space.';body=fold?'The action is centered without querying the division region. Safe-area edge padding alone cannot describe this middle region.':'The preview has a fixed content width. Cropping is a symptom of the implementation, not a reason to detect a particular device model.';}
 else if(state.chapter===3){title='The layout changed; the model did not.';body='The draft and note selection belong to a stable owner above the changing layout. The full-screen open/close transition does not by itself change scenePhase.';}
 else if(state.surface==='tabletop'){title='Portrait placement; optional separation.';body='Horizontal bars belong to the system. This custom teaching layout keeps content above the fold and the action below it; your app need not invent a new mode for this pose.';}
 else if(fold){title='The center is a region, not an edge inset.';body='The fold can become active even when the view’s dimensions stay the same. Query regions during relevant layout updates and verify your update path on a device.';}
 else if(compact){title='Less room calls for fewer visible panes.';body='This demo collapses at its chosen 520-unit budget. On iOS, use actual traits and container behavior; the slider does not predict size classes.';}
 else{title='More room reveals more context.';body='The same list and detail can coexist when there is enough space. Opening the display should not replace the current task or create a second app experience.';}
 byId('decision-title').textContent=title;byId('decision-body').textContent=body;
 byId('system-responsibility').textContent='Container-managed bar placement, standard navigation adaptation, and reserved-region information.';
 byId('app-responsibility').textContent='Custom control geometry, reachable actions, stable model ownership, and testing across transitions.';
}
function changeSurface(key){const old=state.surface;if(old===key)return;state.surface=key;state.width=surfaces[key].width;if(state.mode==='fragile'){state.fragileDraft=initialDraft;state.fragileNote='Learning to adapt';log(`${surfaces[key].label}: fragile layout recreated its demo state. The draft reset.`);}else{log(`${surfaces[key].label}: view geometry changed; selected note and ${state.draft.length}-character draft retained.`);if(state.chapter===3&&state.flags.editedDraft===state.draft&&state.draft!==initialDraft)state.complete.add(3);}if(isFold())log('Division region active in this scenario. Do not assume a resize callback will always accompany folding.');render();checkCompletion();}
chapters.forEach((c,i)=>{const b=document.createElement('button');b.type='button';b.dataset.chapter=String(i);const number=document.createElement('span');number.textContent=String(i+1);b.append(number,document.createTextNode(c.short));b.addEventListener('click',()=>setChapter(i));byId('chapter-nav').append(b);});
for(const b of document.querySelectorAll('button[data-surface]'))b.addEventListener('click',()=>changeSurface(b.dataset.surface));
byId('app-width').addEventListener('input',event=>{state.width=Number(event.target.value);render();checkCompletion();});
byId('app-width').addEventListener('change',()=>log(`Available width set to ${state.width} demo units. ${state.width<520?'One-pane':'Two-pane'} teaching budget.`));
for(const mode of ['fragile','adaptive'])byId(`${mode}-mode`).addEventListener('click',()=>{if(state.mode!==mode){state.mode=mode;log(`${mode==='adaptive'?'Stable-model adaptive':'Fixed-width fragile'} implementation selected.`);}render();checkCompletion();});
byId('camera-active').addEventListener('change',event=>{state.camera=event.target.checked;log(`Inner camera ${state.camera?'active: occlusion region is present':'inactive: camera region removed'} in this scenario.`);render();checkCompletion();});
byId('show-regions').addEventListener('change',event=>{state.regions=event.target.checked;log(`Region guides ${state.regions?'shown':'hidden'}. This changes the overlay only, not the layout’s region information.`);render();});
byId('draft').addEventListener('input',event=>{if(state.mode==='adaptive'){state.draft=event.target.value;if(state.chapter===3)state.flags.editedDraft=state.draft;}else state.fragileDraft=event.target.value;});
byId('draft').addEventListener('change',()=>log(`Demo draft edited (${draftValue().length} characters) in ${state.mode==='adaptive'?'stable model':'layout-local state'}.`));
for(const b of document.querySelectorAll('[data-note]'))b.addEventListener('click',()=>{if(state.mode==='adaptive')state.note=b.dataset.note;else state.fragileNote=b.dataset.note;log(`Selected “${noteValue()}”. The same demo editor is reused.`);render();});
byId('demo-action').addEventListener('click',()=>{if(state.mode==='fragile'&&isFold()){toast('Demo: Compose overlaps the fold. Move it clear of the region.');log('Compose overlaps a division region. Real touches there may be suppressed.');}else{toast('Compose is reachable in this layout.');log('Compose reached successfully in this teaching layout.');}});
for(const b of document.querySelectorAll('[data-tab]')){b.addEventListener('click',()=>setTab(b.dataset.tab));b.addEventListener('keydown',event=>{const tabs=['signals','swift','trace'];let i=tabs.indexOf(b.dataset.tab);if(event.key==='ArrowRight')i=(i+1)%3;else if(event.key==='ArrowLeft')i=(i+2)%3;else if(event.key==='Home')i=0;else if(event.key==='End')i=2;else return;event.preventDefault();setTab(tabs[i],true);});}
byId('clear-trace').addEventListener('click',()=>{state.trace=[];renderTrace();});
byId('copy-snippet').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(byId('swift-code').textContent);toast('Swift pattern copied.');}catch{const range=document.createRange();range.selectNodeContents(byId('swift-code'));const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);toast('Code selected. Press ⌘C or Ctrl+C to copy.');}});
byId('previous-chapter').addEventListener('click',()=>{setChapter(state.chapter-1);byId('chapter-title').scrollIntoView({block:'center'});});
byId('next-chapter').addEventListener('click',()=>{setChapter(state.chapter===4?0:state.chapter+1);byId('chapter-title').scrollIntoView({block:'center'});});
for(const b of document.querySelectorAll('[data-answer]'))b.addEventListener('click',()=>{for(const option of document.querySelectorAll('[data-answer]'))option.setAttribute('aria-pressed',String(option===b));const answer=b.dataset.answer;byId('answer-feedback').textContent=answer==='regions'?'Correct. Size from the view, keep custom controls clear of occlusion regions, and retain the existing model. Validate the real result on a device.':answer==='angle'?'A hinge angle does not describe the current app bounds or camera region. Recreating the model also loses the task. Try using layout information.':'Left and right safe-area insets can differ, and a centered control can intersect an interior reserved region. Use each inset and query regions.';if(answer==='regions'){state.complete.add(4);log('Combined scenario answered: geometry + reserved regions + stable state.');}updateProgress();});
byId('reset-lab').addEventListener('click',()=>{Object.assign(state,{chapter:0,surface:'open',width:760,camera:false,regions:true,mode:'adaptive',draft:initialDraft,fragileDraft:initialDraft,note:'Learning to adapt',fragileNote:'Learning to adapt',complete:new Set(),flags:{},trace:[],seq:0});byId('answer-feedback').textContent='';for(const b of document.querySelectorAll('[data-answer]'))b.setAttribute('aria-pressed','false');log('Guide restarted. Only this page’s demo state was reset.');setChapter(0);});
log('Teaching model ready. Change a control to inspect the effect.');setChapter(0);
